bool subsetSum(vector<int>& a, long long target) {
    int n = a.size();
    for (int mask = 0; mask < (1 << n); mask++) {   // every subset
        long long sum = 0;
        for (int i = 0; i < n; i++)
            if (mask & (1 << i)) sum += a[i];
        if (sum == target) return true;
    }
    return false;
}

