def subset_sums(a):
    n = len(a)
    sums = []
    for mask in range(1 << n):
        s = 0
        for i in range(n):
            if mask & (1 << i):
                s += a[i]
        sums.append(s)
    return sums

def subset_sum_mitm(a, target):
    n = len(a)
    left, right = a[: n // 2], a[n // 2 :]
    A = subset_sums(left)
    B = set(subset_sums(right))          # a set gives O(1) complement lookups
    return any((target - s) in B for s in A)

