boolean subsetSumMITM(int[] a, long target) {
    int n = a.length, h = n / 2;
    long[] A = subsetSums(Arrays.copyOfRange(a, 0, h));
    long[] B = subsetSums(Arrays.copyOfRange(a, h, n));
    Arrays.sort(B);
    for (long s : A)
        if (Arrays.binarySearch(B, target - s) >= 0) return true;   // need the complement
