long long closestSum(vector<int>& a, long long target) {
    int n = a.size();
    vector<long long> A = subsetSums({a.begin(), a.begin() + n/2});
    vector<long long> B = subsetSums({a.begin() + n/2, a.end()});
    sort(B.begin(), B.end());
    long long best = 0;
    for (long long s : A) {
        long long need = target - s;                       // ideal right value
        auto it = upper_bound(B.begin(), B.end(), need);   // first value above need
        if (it != B.begin()) {
            long long cand = s + *prev(it);                // the value at or below need
            if (llabs(target - cand) < llabs(target - best)) best = cand;
        }
    }
    return best;
}

