long closestSum(int[] a, long target) {
    int n = a.length, h = n / 2;
    long[] A = subsetSums(Arrays.copyOfRange(a, 0, h));
    long[] B = subsetSums(Arrays.copyOfRange(a, h, n));
    Arrays.sort(B);
    long best = 0;
    for (long s : A) {
        long need = target - s;                  // ideal right value
        int j = upperBound(B, need);             // first index with value above need
        if (j > 0) {
            long cand = s + B[j - 1];            // the value at or below need
            if (Math.abs(target - cand) < Math.abs(target - best)) best = cand;
        }
    }
    return best;
}

