function closestSum(a, target) {
  const n = a.length, h = n >> 1;
  const A = subsetSums(a.slice(0, h));
  const B = subsetSums(a.slice(h)).sort((x, y) => x - y);
  let best = 0;
  for (const s of A) {
    const need = target - s;                   // ideal right value
    let lo = 0, hi = B.length;                  // upper bound for need
    while (lo < hi) { const m = (lo + hi) >> 1; if (B[m] <= need) lo = m + 1; else hi = m; }
    if (lo > 0) {
      const cand = s + B[lo - 1];              // the value at or below need
      if (Math.abs(target - cand) < Math.abs(target - best)) best = cand;
    }
  }
  return best;
}
